CREATE TABLE app_metadata (key TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL);
CREATE TABLE phase0_seed (id TEXT PRIMARY KEY NOT NULL, member_name TEXT NOT NULL, amount_minor INTEGER NOT NULL, media BLOB NOT NULL);
CREATE TABLE backup_manifest (id INTEGER PRIMARY KEY CHECK (id = 1), format_version INTEGER NOT NULL, schema_version INTEGER NOT NULL, source_app_version TEXT NOT NULL, created_at_utc TEXT NOT NULL, locale TEXT NOT NULL, time_zone TEXT NOT NULL, gym_id TEXT NOT NULL, gym_name TEXT NOT NULL, currency TEXT NOT NULL, record_count INTEGER NOT NULL, money_total_minor INTEGER NOT NULL, media_sha256 TEXT NOT NULL, integrity_result TEXT NOT NULL);
CREATE TABLE avatar_benchmark (id INTEGER PRIMARY KEY NOT NULL, display_name TEXT NOT NULL, avatar BLOB NOT NULL);
CREATE INDEX avatar_benchmark_name_idx ON avatar_benchmark(display_name);
INSERT INTO app_metadata(key, value) VALUES ('schema_owner', 'gymvito');

CREATE TABLE settings (id INTEGER PRIMARY KEY NOT NULL CHECK (id = 1), language TEXT NOT NULL CHECK (language IN ('en', 'hi')), currency_code TEXT NOT NULL DEFAULT 'INR', date_format TEXT NOT NULL DEFAULT 'day-month-year' CHECK (date_format IN ('day-month-year', 'month-day-year', 'year-month-day')), time_format TEXT NOT NULL DEFAULT '12-hour' CHECK (time_format IN ('12-hour', '24-hour')), week_starts_on INTEGER NOT NULL DEFAULT 1 CHECK (week_starts_on IN (0, 1)), financial_year_start_month INTEGER NOT NULL DEFAULT 4 CHECK (financial_year_start_month BETWEEN 1 AND 12), financial_year_start_day INTEGER NOT NULL DEFAULT 1 CHECK (financial_year_start_day BETWEEN 1 AND 31), inactivity_timeout_seconds INTEGER NOT NULL DEFAULT 300 CHECK (inactivity_timeout_seconds BETWEEN 30 AND 3600), biometrics_enabled INTEGER NOT NULL DEFAULT 0 CHECK (biometrics_enabled IN (0, 1)), onboarding_step TEXT NOT NULL DEFAULT 'gym' CHECK (onboarding_step IN ('gym', 'security', 'backup-intro', 'complete')), setup_completed_at_utc TEXT, created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL);
CREATE TABLE gym_profile (id TEXT PRIMARY KEY NOT NULL, singleton_key INTEGER NOT NULL UNIQUE DEFAULT 1 CHECK (singleton_key = 1), name TEXT NOT NULL, owner_name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', logo_uri TEXT, receipt_footer TEXT NOT NULL DEFAULT '', created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL);
CREATE TABLE role (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL UNIQUE, is_system INTEGER NOT NULL DEFAULT 1 CHECK (is_system IN (0, 1)));
CREATE TABLE role_permission (role_id TEXT NOT NULL REFERENCES role(id) ON DELETE CASCADE, capability TEXT NOT NULL, allowed INTEGER NOT NULL CHECK (allowed IN (0, 1)), PRIMARY KEY (role_id, capability));
CREATE TABLE staff_profile (id TEXT PRIMARY KEY NOT NULL, display_name TEXT NOT NULL, role_id TEXT NOT NULL REFERENCES role(id), pin_verifier_json TEXT NOT NULL, preferred_language TEXT NOT NULL CHECK (preferred_language IN ('en', 'hi')), is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)), is_owner INTEGER NOT NULL DEFAULT 0 CHECK (is_owner IN (0, 1)), failed_pin_attempts INTEGER NOT NULL DEFAULT 0 CHECK (failed_pin_attempts >= 0), locked_until_utc TEXT, last_unlocked_at_utc TEXT, created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL);
CREATE UNIQUE INDEX staff_profile_single_owner_idx ON staff_profile(is_owner) WHERE is_owner = 1;
CREATE TABLE security_event (id TEXT PRIMARY KEY NOT NULL, occurred_at_utc TEXT NOT NULL, actor_staff_id TEXT REFERENCES staff_profile(id), event_type TEXT NOT NULL, outcome TEXT NOT NULL, metadata_code TEXT);
CREATE INDEX security_event_occurred_idx ON security_event(occurred_at_utc);
CREATE TABLE audit_event (id TEXT PRIMARY KEY NOT NULL, occurred_at_utc TEXT NOT NULL, actor_staff_id TEXT REFERENCES staff_profile(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, summary_code TEXT NOT NULL);
CREATE INDEX audit_event_occurred_idx ON audit_event(occurred_at_utc);
INSERT INTO role(id, name, is_system) VALUES ('owner', 'Owner', 1), ('manager', 'Manager', 1), ('front-desk', 'Front Desk', 1);
INSERT INTO role_permission(role_id, capability, allowed) VALUES ('owner', 'manage_members', 1), ('owner', 'manage_billing', 1), ('owner', 'view_reports', 1), ('owner', 'manage_settings', 1), ('owner', 'manage_staff', 1), ('owner', 'backup_restore', 1), ('manager', 'manage_members', 1), ('manager', 'manage_billing', 1), ('manager', 'view_reports', 1), ('manager', 'manage_settings', 0), ('manager', 'manage_staff', 0), ('manager', 'backup_restore', 0), ('front-desk', 'manage_members', 1), ('front-desk', 'manage_billing', 1), ('front-desk', 'view_reports', 0), ('front-desk', 'manage_settings', 0), ('front-desk', 'manage_staff', 0), ('front-desk', 'backup_restore', 0);

CREATE TABLE number_sequences (sequence_key TEXT PRIMARY KEY NOT NULL, next_value INTEGER NOT NULL CHECK (next_value > 0));
INSERT INTO number_sequences(sequence_key, next_value) VALUES ('member_code', 1);
CREATE TABLE plan (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, normalized_name TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', duration_value INTEGER NOT NULL CHECK (duration_value > 0), duration_unit TEXT NOT NULL CHECK (duration_unit IN ('day', 'week', 'month', 'year')), price_minor INTEGER NOT NULL CHECK (price_minor >= 0), admission_fee_minor INTEGER NOT NULL DEFAULT 0 CHECK (admission_fee_minor >= 0), currency_code TEXT NOT NULL, tax_label TEXT NOT NULL DEFAULT '', tax_rate_basis_points INTEGER NOT NULL DEFAULT 0 CHECK (tax_rate_basis_points BETWEEN 0 AND 10000), discount_type TEXT NOT NULL DEFAULT 'none' CHECK (discount_type IN ('none', 'fixed', 'percentage')), discount_value INTEGER NOT NULL DEFAULT 0 CHECK (discount_value >= 0), color_hex TEXT NOT NULL DEFAULT '#0D6659', freeze_allowed INTEGER NOT NULL DEFAULT 0 CHECK (freeze_allowed IN (0, 1)), max_freeze_days INTEGER, freeze_extends_end_date INTEGER NOT NULL DEFAULT 0 CHECK (freeze_extends_end_date IN (0, 1)), renewal_behavior TEXT NOT NULL DEFAULT 'ask' CHECK (renewal_behavior IN ('immediate', 'after-expiry', 'ask')), is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)), created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL);
CREATE INDEX plan_active_name_idx ON plan(is_active, normalized_name);
CREATE TABLE member (id TEXT PRIMARY KEY NOT NULL, member_code TEXT NOT NULL UNIQUE, normalized_member_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, normalized_name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', normalized_phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', normalized_email TEXT NOT NULL DEFAULT '', date_of_birth TEXT, gender TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', emergency_contact_name TEXT NOT NULL DEFAULT '', emergency_contact_phone TEXT NOT NULL DEFAULT '', joining_source TEXT NOT NULL DEFAULT '', is_archived INTEGER NOT NULL DEFAULT 0 CHECK (is_archived IN (0, 1)), archived_at_utc TEXT, created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL);
CREATE INDEX member_name_search_idx ON member(normalized_name);
CREATE INDEX member_phone_search_idx ON member(normalized_phone);
CREATE INDEX member_email_search_idx ON member(normalized_email);
CREATE INDEX member_code_search_idx ON member(normalized_member_code);
CREATE INDEX member_archive_recent_idx ON member(is_archived, updated_at_utc DESC);
CREATE TABLE member_note (id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES member(id) ON DELETE CASCADE, content TEXT NOT NULL, actor_staff_id TEXT REFERENCES staff_profile(id), created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL);
CREATE INDEX member_note_member_created_idx ON member_note(member_id, created_at_utc DESC);
CREATE TABLE member_media (id TEXT PRIMARY KEY NOT NULL, member_id TEXT NOT NULL REFERENCES member(id) ON DELETE CASCADE, media_type TEXT NOT NULL CHECK (media_type = 'profile_photo'), mime_type TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK (byte_size > 0 AND byte_size <= 262144), width INTEGER NOT NULL CHECK (width > 0), height INTEGER NOT NULL CHECK (height > 0), content BLOB NOT NULL, created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL, UNIQUE(member_id, media_type));
CREATE INDEX member_media_member_type_idx ON member_media(member_id, media_type);
